 struct EffectBackend{inner:Backend,effects:std::collections::VecDeque<Vec<Value>>}
 impl EffectBackend{fn apply(&mut self,m:&mut BTreeMap<u32,Memory>){let effects=self.effects.pop_front().expect("explicit native service effects");self.inner.calls.last_mut().unwrap()["supplied_effects"]=json!(effects);for effect in effects{let r=effect["reference"].as_u64().unwrap()as u32;let raw=bytes(effect["raw"].as_str().unwrap());for(j,v)in raw.into_iter().enumerate(){let a=r+j as u32;let base=*m.range(..=a).next_back().unwrap().0;let offset=(a-base)as usize;m.get_mut(&base).unwrap().raw[offset]=v;}}}}
 impl crate::audio_path_voice_empty_source_release::Services for EffectBackend{fn free(&mut self,p:u32,r:u32,m:&mut BTreeMap<u32,Memory>)->Result<(),Error>{crate::audio_path_voice_empty_source_release::Services::free(&mut self.inner,p,r,m)?;self.apply(m);Ok(())}}
 impl crate::audio_action_registry_key_publication::Services for EffectBackend{fn allocate(&mut self,p:u32,z:u32,m:&mut BTreeMap<u32,Memory>,d:&mut BTreeSet<u32>)->Result<Option<u32>,Error>{let result=crate::audio_action_registry_key_publication::Services::allocate(&mut self.inner,p,z,m,d)?;self.apply(m);Ok(result)}}
 impl Services for EffectBackend{fn observe_curve_unlink(&mut self,target:u32,m:&BTreeMap<u32,Memory>){self.inner.observe_curve_unlink(target,m);}}
